mapper.select:
SELECT * FROM ds_agent_run
WHERE tenant_id = #{tenantId} AND session_id = #{sessionId}
ORDER BY created_at ASC, id ASC

mapper.update:
UPDATE ds_agent_run
status = #{to}, revision = revision + 1, updated_at = #{now}, started_at = #{payload.startedAt}, finished_at = #{payload.finishedAt}, error_code = #{payload.errorCode}, safe_message = #{payload.safeMessage}, usage_json = #{payload.usageJson},
WHERE id = #{id} AND tenant_id = #{tenantId} AND revision = #{expectedRevision}
